    /*
     * Add to the CorrectiveActions
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Issue
     */
    public Issue addToCorrectiveActions( UUID parentId, CorrectiveAction addTo ) {
	    LOGGER.info("handling AssignCorrectiveActionsToIssueEvent - " );
	    
	    Issue parentEntity = repository.findById(parentId).get();
	    CorrectiveAction child = registry.project( CorrectiveAction.class, addTo.getCorrectiveActionId());
	    
	    parentEntity.getCorrectiveActions().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the CorrectiveActions
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Issue
     */
	public Issue removeFromCorrectiveActions( UUID parentId, CorrectiveAction removeFrom ) {
	    LOGGER.info("handling RemoveCorrectiveActionsFromIssueEvent " );
	
	    Issue parentEntity = repository.findById(parentId).get();
	    CorrectiveAction child = registry.project( CorrectiveAction.class, removeFrom.getCorrectiveActionId());
	    
	    parentEntity.getCorrectiveActions().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Issue via an FindIssueQuery
     * @return 	query	FindIssueQuery
     */
    @SuppressWarnings("unused")
    public Issue find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Issue - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Issues
     *
     * @param	query	FindAllIssueQuery 
     * @return 	List<Issue> 
     */
    @SuppressWarnings("unused")
    public List<Issue> findAll( FindAllIssueQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Issue - {0}", exc.getMessage() );
    	}
    	return null;
    }


